package com.rikkeibank.account.config; import com.rikkeibank.account.model.*; import com.rikkeibank.account.repository.*; import java.math.BigDecimal; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*;
@Configuration public class DataInitializer{@Bean CommandLineRunner seed(AccountTypeRepository tr,BankAccountRepository ar){return a->{AccountType t=tr.findByCode("SAVINGS").orElseGet(()->{AccountType x=new AccountType();x.setCode("SAVINGS");x.setName("Tài khoản tiết kiệm");x.setDescription("Tài khoản mẫu");return tr.save(x);});if(ar.count()==0){BankAccount b1=new BankAccount();b1.setAccountNumber("10001001");b1.setOwnerUsername("customer01");b1.setAccountType(t);b1.setBalance(new BigDecimal("5000000.00"));ar.save(b1);BankAccount b2=new BankAccount();b2.setAccountNumber("10001002");b2.setOwnerUsername("customer02");b2.setAccountType(t);b2.setBalance(new BigDecimal("2000000.00"));ar.save(b2);}};}}
